mapper.select:
select D.* from(SELECT A.ID AS ID, A.NAME AS NAME, A.TYPE AS TYPE, A.product_time AS productTime, A.actual_time AS asactualTime, A.description AS description, A.lng_min AS lngMin, A.lng_max AS lngMax, A.lat_min AS latMin, A.lat_max AS latMax, A.keywords AS keyWords, A.remark AS remark, A.data_type AS dataType, A.extent as extent, A.meta_data as metaData, A.min_level as minLevel, A.max_level as maxLevel, C.catalog_id as catalogId FROM bus_catalog_data_info C inner join bus_data_info A on C.data_id=A.id where C.catalog_id IN
#{datasetId}
and A.product_time between TO_DATE(#{bo.beginTime},'YYYY-MM-DD') and TO_DATE(#{bo.endTime},'YYYY-MM-DD') ) D
where ST_Intersects(ST_Transform(D.extent,3857),st_buffer(ST_Transform(ST_GeomFromText(#{bo.local.value.center.wkt},4326),3857),#{bo.local.value.radius}))
where ST_Intersects(D.extent,ST_GeomFromText(#{bo.local.value.wkt},4326))
left join bus_region_info E on ST_Intersects(D.extent,E.geometry) where
E.code=#{bo.local.value.city}
E.code=#{bo.local.value.prov}
where ST_Intersects(D.extent,ST_GeomFromText(#{bo.local.value.wkt},4326))

select D.* from(SELECT A.ID AS ID, A.NAME AS NAME, A.TYPE AS TYPE, A.product_time AS productTime, A.actual_time AS asactualTime, A.description AS description, A.lng_min AS lngMin, A.lng_max AS lngMax, A.lat_min AS latMin, A.lat_max AS latMax, A.keywords AS keyWords, A.remark AS remark, A.data_type AS dataType, A.extent as extent, A.meta_data as metaData, A.min_level as minLevel, A.max_level as maxLevel, C.catalog_id as catalogId FROM st_user_catalog_data_info C inner join bus_data_info A on C.data_id=A.id where C.catalog_id IN
#{datasetId}
and C.user_id=#{bo.userId}
and A.product_time between TO_DATE(#{bo.beginTime},'YYYY-MM-DD') and TO_DATE(#{bo.endTime},'YYYY-MM-DD') ) D
where ST_Intersects(ST_Transform(D.extent,3857),st_buffer(ST_Transform(ST_GeomFromText(#{bo.local.value.center.wkt},4326),3857),#{bo.local.value.radius}))
where ST_Intersects(D.extent,ST_GeomFromText(#{bo.local.value.wkt},4326))
left join bus_region_info E on ST_Intersects(D.extent,E.geometry) where
E.code=#{bo.local.value.city}
E.code=#{bo.local.value.prov}
where ST_Intersects(D.extent,ST_GeomFromText(#{bo.local.value.wkt},4326))

select D.* from(SELECT A.ID AS ID, A.NAME AS NAME, A.TYPE AS TYPE, A.product_time AS productTime, A.actual_time AS asactualTime, A.description AS description, A.lng_min AS lngMin, A.lng_max AS lngMax, A.lat_min AS latMin, A.lat_max AS latMax, A.keywords AS keyWords, A.remark AS remark, A.data_type AS dataType, A.extent as extent, A.meta_data as metaData, A.min_level as minLevel, A.max_level as maxLevel, C.catalog_id as catalogId FROM bus_catalog_data_info C inner join bus_data_info A on C.data_id=A.id where C.catalog_id IN
#{datasetId}
and A.product_time between TO_DATE(#{bo.beginTime},'YYYY-MM-DD') and TO_DATE(#{bo.endTime},'YYYY-MM-DD')
UNION ALL
SELECT A.ID AS ID, A.NAME AS NAME, A.TYPE AS TYPE, A.product_time AS productTime, A.actual_time AS asactualTime, A.description AS description, A.lng_min AS lngMin, A.lng_max AS lngMax, A.lat_min AS latMin, A.lat_max AS latMax, A.keywords AS keyWords, A.remark AS remark, A.data_type AS dataType, A.extent as extent, A.meta_data as metaData, A.min_level as minLevel, A.max_level as maxLevel, C.catalog_id as catalogId FROM st_user_catalog_data_info C inner join bus_data_info A on C.data_id=A.id where C.catalog_id IN
#{datasetId}
and C.user_id=#{bo.userId}
and A.product_time between TO_DATE(#{bo.beginTime},'YYYY-MM-DD') and TO_DATE(#{bo.endTime},'YYYY-MM-DD')
) D
where ST_Intersects(ST_Transform(D.extent,3857),st_buffer(ST_Transform(ST_GeomFromText(#{bo.local.value.center.wkt},4326),3857),#{bo.local.value.radius}))
where ST_Intersects(D.extent,ST_GeomFromText(#{bo.local.value.wkt},4326))
left join bus_region_info E on ST_Intersects(D.extent,E.geometry) where
E.code=#{bo.local.value.city}
E.code=#{bo.local.value.prov}
where ST_Intersects(D.extent,ST_GeomFromText(#{bo.local.value.wkt},4326))

select ST_INTERSECTS(A.extent, B.extent)
from (SELECT extent from bus_data_info where id = #{id1}) A,
     (SELECT extent from bus_data_info where id = #{id2}) B
